#include "htb/tiling.h"

#include <limits.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum { BT_LEFT=0, BT_RIGHT=1, BT_TOP=2, BT_BOTTOM_LEFT=3, BT_BOTTOM_RIGHT=4 };
/* Every accepted column must also have representable 2k and 2k+1 edge keys. */
#define BT_COLUMN_MIN (INT64_MIN / 2)
#define BT_COLUMN_MAX (INT64_MAX / 2)

static int64_t tile_level(const htb_tile_id*t){return(int64_t)t->provider_words[0];}
static int64_t tile_column(const htb_tile_id*t){return(int64_t)t->provider_words[1];}
static int64_t floor_half(int64_t k){return k/2-((k<0&&k%2)!=0);}

static void make_tile(htb_tile_id*t,int64_t level,int64_t column){
    memset(t,0,sizeof(*t));snprintf(t->key,sizeof(t->key),"binary:%lld,%lld",(long long)level,(long long)column);snprintf(t->label,sizeof(t->label),"level %lld, column %lld",(long long)level,(long long)column);snprintf(t->type,sizeof(t->type),"horocyclic-pentagon");t->provider_words[0]=(uint64_t)level;t->provider_words[1]=(uint64_t)column;t->provider_word_count=2;t->coordinates[0]=level;t->coordinates[1]=column;t->coordinate_count=2;
}
static const char*edge_label(int edge){static const char*labels[]={"left","right","parent","child left","child right"};return edge>=0&&edge<5?labels[edge]:"unknown";}
static void make_edge(const htb_tile_id*tile,int edge,htb_edge_ref*out){
    int64_t n=tile_level(tile),k=tile_column(tile);memset(out,0,sizeof(*out));out->local_index=edge;out->owner_normal_sign=(edge==BT_LEFT||edge==BT_BOTTOM_LEFT||edge==BT_BOTTOM_RIGHT)?1:-1;snprintf(out->label,sizeof(out->label),"%s",edge_label(edge));
    if(edge==BT_LEFT)snprintf(out->boundary_key,sizeof(out->boundary_key),"binary:v:%lld:%lld",(long long)n,(long long)k);
    else if(edge==BT_RIGHT)snprintf(out->boundary_key,sizeof(out->boundary_key),"binary:v:%lld:%lld",(long long)n,(long long)(k+1));
    else if(edge==BT_TOP)snprintf(out->boundary_key,sizeof(out->boundary_key),"binary:h:%lld:%lld",(long long)n,(long long)k);
    else if(edge==BT_BOTTOM_LEFT)snprintf(out->boundary_key,sizeof(out->boundary_key),"binary:h:%lld:%lld",(long long)(n-1),(long long)(2*k));
    else if(edge==BT_BOTTOM_RIGHT)snprintf(out->boundary_key,sizeof(out->boundary_key),"binary:h:%lld:%lld",(long long)(n-1),(long long)(2*k+1));
}

static int scalar_pow2(htb_arith_ctx*ctx,htb_scalar*out,int64_t exponent){
    if(exponent<-4096||exponent>4096)return 0;htb_scalar two,tmp;htb_scalar_init(ctx,&two);htb_scalar_init(ctx,&tmp);int ok=htb_scalar_set_si(out,1)&&htb_scalar_set_si(&two,2);int64_t count=exponent<0?-exponent:exponent;for(int64_t i=0;i<count&&ok;i++){if(exponent>=0)ok=htb_scalar_mul(&tmp,out,&two);else ok=htb_scalar_div(&tmp,out,&two);if(ok)ok=htb_scalar_set(out,&tmp);}htb_scalar_clear(&two);htb_scalar_clear(&tmp);return ok;
}
static int scaled_integer(htb_arith_ctx*ctx,htb_scalar*out,int64_t value,const htb_scalar*scale){htb_scalar v;htb_scalar_init(ctx,&v);int ok=htb_scalar_set_si(&v,value)&&htb_scalar_mul(out,&v,scale);htb_scalar_clear(&v);return ok;}

/* Cayley transform z=x+iy -> w=(z-i)/(z+i), with infinity at disk point (1,0). */
static int from_reference(const htb_tiling*t,const htb_vec2*r,htb_vec2*d,char*error,size_t error_size){
    htb_cmp positive=htb_scalar_compare_si(&r->y,0);if(positive!=HTB_CMP_GREATER){snprintf(error,error_size,"upper-half-plane y must be positive");return 0;}htb_arith_ctx*ctx=t->arith;htb_scalar x2,y2,yp,den,tmp,one,two;htb_scalar*all[]={&x2,&y2,&yp,&den,&tmp,&one,&two};for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_init(ctx,all[i]);htb_scalar_set_si(&one,1);htb_scalar_set_si(&two,2);int ok=htb_scalar_sqr(&x2,&r->x)&&htb_scalar_sqr(&y2,&r->y)&&htb_scalar_add(&yp,&r->y,&one)&&htb_scalar_sqr(&den,&yp)&&htb_scalar_add(&den,&den,&x2)&&htb_scalar_add(&tmp,&x2,&y2)&&htb_scalar_sub(&tmp,&tmp,&one)&&htb_scalar_div(&d->x,&tmp,&den)&&htb_scalar_mul(&tmp,&r->x,&two)&&htb_scalar_neg(&tmp,&tmp)&&htb_scalar_div(&d->y,&tmp,&den);for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_clear(all[i]);return ok;
}
static int to_reference(const htb_tiling*t,const htb_vec2*d,htb_vec2*r,char*error,size_t error_size){
    htb_cmp inside;if(!htb_disk_contains(d,&inside)||inside!=HTB_CMP_LESS){snprintf(error,error_size,"point must be certified strictly inside the disk");return 0;}htb_arith_ctx*ctx=t->arith;htb_scalar um,den,r2,tmp,one,two;htb_scalar*all[]={&um,&den,&r2,&tmp,&one,&two};for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_init(ctx,all[i]);htb_scalar_set_si(&one,1);htb_scalar_set_si(&two,2);int ok=htb_scalar_sub(&um,&one,&d->x)&&htb_scalar_sqr(&den,&um)&&htb_scalar_sqr(&tmp,&d->y)&&htb_scalar_add(&den,&den,&tmp)&&htb_scalar_mul(&tmp,&d->y,&two)&&htb_scalar_neg(&tmp,&tmp)&&htb_scalar_div(&r->x,&tmp,&den)&&htb_scalar_sqr(&r2,&d->x)&&htb_scalar_sqr(&tmp,&d->y)&&htb_scalar_add(&r2,&r2,&tmp)&&htb_scalar_sub(&tmp,&one,&r2)&&htb_scalar_div(&r->y,&tmp,&den);for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_clear(all[i]);return ok;
}

static int initialize(htb_tiling*t,const htb_tiling_config*config,char*error,size_t error_size){(void)t;(void)config;(void)error;(void)error_size;return 1;}
static void clear_tiling(htb_tiling*t){(void)t;}

static int coordinate_index(const htb_scalar*x,int64_t*index,int*on,char*error,size_t error_size){
    double a=htb_scalar_get_approx(x);if(!isfinite(a)||a<(double)BT_COLUMN_MIN+4||a>(double)BT_COLUMN_MAX-4){snprintf(error,error_size,"binary tile column is outside the supported integer range");return 0;}int64_t seed=(int64_t)floor(a);for(int delta=-2;delta<=2;delta++){int64_t k=seed+delta;if(k<BT_COLUMN_MIN||k>BT_COLUMN_MAX)continue;htb_cmp lo=htb_scalar_compare_si(x,k),hi=htb_scalar_compare_si(x,k+1);if(lo==HTB_CMP_EQUAL){*index=k;*on=1;return 1;}if(lo==HTB_CMP_GREATER&&hi==HTB_CMP_LESS){*index=k;*on=0;return 1;}if(lo==HTB_CMP_UNRESOLVED||hi==HTB_CMP_UNRESOLVED){snprintf(error,error_size,"binary tile column could not be certified at current precision");return 0;}}snprintf(error,error_size,"point is not certifiably contained in a binary tile column");return 0;
}
static int level_index(const htb_tiling*t,const htb_scalar*y,int64_t*level,int*on,htb_scalar*scale,char*error,size_t error_size){
    double a=htb_scalar_get_approx(y);if(!(a>0)){snprintf(error,error_size,"upper-half-plane coordinate is not positive");return 0;}int64_t n=isfinite(a)?(int64_t)floor(log2(a)):0;if(n<-4096)n=-4096;if(n>4096)n=4096;htb_scalar twice;htb_scalar_init(t->arith,&twice);for(int attempt=0;attempt<8194;attempt++){if(!scalar_pow2(t->arith,scale,n)||!htb_scalar_add(&twice,scale,scale))break;htb_cmp lo=htb_scalar_compare(y,scale),hi=htb_scalar_compare(y,&twice);if(lo==HTB_CMP_UNRESOLVED||hi==HTB_CMP_UNRESOLVED||lo==HTB_CMP_ERROR||hi==HTB_CMP_ERROR){snprintf(error,error_size,"binary level could not be certified at current precision");htb_scalar_clear(&twice);return 0;}if(lo==HTB_CMP_LESS){if(--n<-4096)break;continue;}if(hi==HTB_CMP_GREATER||hi==HTB_CMP_EQUAL){if(++n>4096)break;continue;}*level=n;*on=lo==HTB_CMP_EQUAL;htb_scalar_clear(&twice);return 1;}htb_scalar_clear(&twice);snprintf(error,error_size,"binary level is outside the supported range");return 0;
}
static int locate_point(const htb_tiling*t,const htb_vec2*point,htb_point_location*location,char*error,size_t error_size){
    htb_vec2 ref;htb_vec2_init(t->arith,&ref);htb_scalar scale,q,mid,half;htb_scalar_init(t->arith,&scale);htb_scalar_init(t->arith,&q);htb_scalar_init(t->arith,&mid);htb_scalar_init(t->arith,&half);int64_t n=0,k=0;int on_h=0,on_v=0;int ok=to_reference(t,point,&ref,error,error_size)&&level_index(t,&ref.y,&n,&on_h,&scale,error,error_size)&&htb_scalar_div(&q,&ref.x,&scale)&&coordinate_index(&q,&k,&on_v,error,error_size);if(ok){make_tile(&location->tile,n,k);htb_edge_ref edge;if(on_v){make_edge(&location->tile,BT_LEFT,&edge);ok=htb_edge_list_append(&location->incident_edges,&edge);}if(ok&&on_h){htb_scalar_parse_rational(&half,"1/2",error,error_size);htb_scalar_set_si(&mid,k);htb_scalar_add(&mid,&mid,&half);htb_cmp side=htb_scalar_compare(&q,&mid);if(side==HTB_CMP_LESS||side==HTB_CMP_EQUAL){make_edge(&location->tile,BT_BOTTOM_LEFT,&edge);ok=htb_edge_list_append(&location->incident_edges,&edge);}if(ok&&(side==HTB_CMP_GREATER||side==HTB_CMP_EQUAL)){make_edge(&location->tile,BT_BOTTOM_RIGHT,&edge);ok=htb_edge_list_append(&location->incident_edges,&edge);}if(side==HTB_CMP_UNRESOLVED||side==HTB_CMP_ERROR){snprintf(error,error_size,"binary bottom-edge incidence is unresolved");ok=0;}}}htb_scalar_clear(&scale);htb_scalar_clear(&q);htb_scalar_clear(&mid);htb_scalar_clear(&half);htb_vec2_clear(&ref);return ok;
}
static int enumerate_edges(const htb_tiling*t,const htb_tile_id*tile,htb_edge_list*edges,char*error,size_t error_size){(void)t;(void)error;(void)error_size;for(int i=0;i<5;i++){htb_edge_ref edge;make_edge(tile,i,&edge);if(!htb_edge_list_append(edges,&edge))return 0;}return 1;}

static int adjacent(const htb_tiling*t,const htb_tile_id*tile,const htb_edge_ref*edge,htb_adjacency*out,char*error,size_t error_size){
    (void)t;int64_t n=tile_level(tile),k=tile_column(tile),nn=n,nk=k;int reverse=-1;if(edge->local_index==BT_LEFT){if(k==BT_COLUMN_MIN)goto range;nk=k-1;reverse=BT_RIGHT;}else if(edge->local_index==BT_RIGHT){if(k==BT_COLUMN_MAX)goto range;nk=k+1;reverse=BT_LEFT;}else if(edge->local_index==BT_TOP){nn=n+1;nk=floor_half(k);reverse=k-2*nk==0?BT_BOTTOM_LEFT:BT_BOTTOM_RIGHT;}else if(edge->local_index==BT_BOTTOM_LEFT||edge->local_index==BT_BOTTOM_RIGHT){if(k<BT_COLUMN_MIN/2||k>BT_COLUMN_MAX/2)goto range;nn=n-1;nk=2*k+(edge->local_index==BT_BOTTOM_RIGHT);reverse=BT_TOP;}else{snprintf(error,error_size,"invalid binary edge");return 0;}if(nn<-4096||nn>4096){snprintf(error,error_size,"binary adjacency exceeds supported level range");return 0;}out->source=*tile;out->source_edge=*edge;make_tile(&out->neighbor,nn,nk);make_edge(&out->neighbor,reverse,&out->neighbor_edge);return 1;
range:snprintf(error,error_size,"binary adjacency exceeds supported column range");return 0;
}

static int parse_boundary(const htb_edge_ref*edge,char*kind,int64_t*n,int64_t*k){long long a=0,b=0;if(sscanf(edge->boundary_key,"binary:%c:%lld:%lld",kind,&a,&b)!=3)return 0;*n=(int64_t)a;*k=(int64_t)b;return *kind=='v'||*kind=='h';}
static int same_supporting_curve(const htb_edge_ref*edge,const char*entry){char kind;int64_t n,k;htb_edge_ref other;memset(&other,0,sizeof(other));snprintf(other.boundary_key,sizeof(other.boundary_key),"%s",entry?entry:"");char other_kind;int64_t other_n,other_k;if(!parse_boundary(edge,&kind,&n,&k)||!parse_boundary(&other,&other_kind,&other_n,&other_k))return 0;(void)k;(void)other_k;return kind=='h'&&other_kind=='h'&&n==other_n;}
/* A(u^2+v^2)+B u+C v+D=0. */
static int boundary_coefficients(const htb_tiling*t,const htb_edge_ref*edge,htb_scalar*A,htb_scalar*B,htb_scalar*C,htb_scalar*D){
    char kind;int64_t n,k;if(!parse_boundary(edge,&kind,&n,&k))return 0;htb_scalar scale,value,two,one;htb_scalar_init(t->arith,&scale);htb_scalar_init(t->arith,&value);htb_scalar_init(t->arith,&two);htb_scalar_init(t->arith,&one);htb_scalar_set_si(&two,2);htb_scalar_set_si(&one,1);int ok=scalar_pow2(t->arith,&scale,kind=='v'?n:n+1);if(kind=='v'){if(ok)ok=scaled_integer(t->arith,&value,k,&scale)&&htb_scalar_set(A,&value)&&htb_scalar_mul(B,&value,&two)&&htb_scalar_neg(B,B)&&htb_scalar_set_si(C,2)&&htb_scalar_set(D,&value);}else if(ok)ok=htb_scalar_add(A,&scale,&one)&&htb_scalar_mul(B,&scale,&two)&&htb_scalar_neg(B,B)&&htb_scalar_set_si(C,0)&&htb_scalar_sub(D,&scale,&one);htb_scalar_clear(&scale);htb_scalar_clear(&value);htb_scalar_clear(&two);htb_scalar_clear(&one);return ok;
}
static int normal_at(const htb_tiling*t,const htb_edge_ref*edge,const htb_vec2*p,htb_vec2*n,char*error,size_t error_size){
    htb_scalar A,B,C,D,two,tmp;htb_scalar*all[]={&A,&B,&C,&D,&two,&tmp};for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_init(t->arith,all[i]);htb_scalar_set_si(&two,2);int ok=boundary_coefficients(t,edge,&A,&B,&C,&D)&&htb_scalar_mul(&tmp,&A,&p->x)&&htb_scalar_mul(&tmp,&tmp,&two)&&htb_scalar_add(&n->x,&tmp,&B)&&htb_scalar_mul(&tmp,&A,&p->y)&&htb_scalar_mul(&tmp,&tmp,&two)&&htb_scalar_add(&n->y,&tmp,&C);if(!ok&&error&&error_size)snprintf(error,error_size,"failed to construct binary boundary normal");for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_clear(all[i]);return ok;
}

static int edge_reference_vertices(const htb_tiling*t,const htb_tile_id*tile,const htb_edge_ref*edge,htb_vec2*a,htb_vec2*b){
    int64_t n=tile_level(tile),k=tile_column(tile);htb_scalar h,half,kh,next,mid,two;htb_scalar_init(t->arith,&h);htb_scalar_init(t->arith,&half);htb_scalar_init(t->arith,&kh);htb_scalar_init(t->arith,&next);htb_scalar_init(t->arith,&mid);htb_scalar_init(t->arith,&two);htb_scalar_parse_rational(&half,"1/2",NULL,0);htb_scalar_set_si(&two,2);int ok=scalar_pow2(t->arith,&h,n)&&scaled_integer(t->arith,&kh,k,&h)&&scaled_integer(t->arith,&next,k+1,&h);if(ok)ok=htb_scalar_add(&mid,&kh,&next)&&htb_scalar_mul(&mid,&mid,&half);if(ok&&(edge->local_index==BT_LEFT||edge->local_index==BT_RIGHT)){ok=htb_scalar_set(&a->x,edge->local_index==BT_LEFT?&kh:&next)&&htb_scalar_set(&b->x,&a->x)&&htb_scalar_set(&a->y,&h)&&htb_scalar_mul(&b->y,&h,&two);}else if(ok){ok=htb_scalar_set(&a->y,edge->local_index==BT_TOP?&h:&h)&&htb_scalar_set(&b->y,&a->y);if(ok&&edge->local_index==BT_TOP)ok=htb_scalar_mul(&a->y,&h,&two)&&htb_scalar_set(&b->y,&a->y);if(ok&&edge->local_index==BT_TOP)ok=htb_scalar_set(&a->x,&kh)&&htb_scalar_set(&b->x,&next);else if(ok&&edge->local_index==BT_BOTTOM_LEFT)ok=htb_scalar_set(&a->x,&kh)&&htb_scalar_set(&b->x,&mid);else if(ok&&edge->local_index==BT_BOTTOM_RIGHT)ok=htb_scalar_set(&a->x,&mid)&&htb_scalar_set(&b->x,&next);else if(ok)ok=0;}htb_scalar_clear(&h);htb_scalar_clear(&half);htb_scalar_clear(&kh);htb_scalar_clear(&next);htb_scalar_clear(&mid);htb_scalar_clear(&two);return ok;
}
static htb_intersection_state validate_candidate(const htb_tiling*t,htb_intersection*c,const htb_vec2*p,const htb_vec2*v,const htb_tile_id*tile){
    htb_cmp time=htb_scalar_compare_si(&c->time,0);if(time==HTB_CMP_LESS||time==HTB_CMP_EQUAL)return HTB_INTERSECTION_INVALID;if(time==HTB_CMP_UNRESOLVED||time==HTB_CMP_ERROR)return HTB_INTERSECTION_UNRESOLVED;if(!htb_ray_point(&c->point,p,v,&c->time))return HTB_INTERSECTION_INVALID;htb_cmp inside;if(!htb_disk_contains(&c->point,&inside)||inside!=HTB_CMP_LESS)return inside==HTB_CMP_UNRESOLVED?HTB_INTERSECTION_UNRESOLVED:HTB_INTERSECTION_INVALID;
    htb_vec2 ref,a,b;htb_vec2_init(t->arith,&ref);htb_vec2_init(t->arith,&a);htb_vec2_init(t->arith,&b);htb_intersection_state state=HTB_INTERSECTION_VALID;if(!to_reference(t,&c->point,&ref,NULL,0)||!edge_reference_vertices(t,tile,&c->edge,&a,&b))state=HTB_INTERSECTION_UNRESOLVED;else{const htb_scalar*coordinate=(c->edge.local_index==BT_LEFT||c->edge.local_index==BT_RIGHT)?&ref.y:&ref.x;const htb_scalar*lo=(c->edge.local_index==BT_LEFT||c->edge.local_index==BT_RIGHT)?&a.y:&a.x;const htb_scalar*hi=(c->edge.local_index==BT_LEFT||c->edge.local_index==BT_RIGHT)?&b.y:&b.x;htb_cmp l=htb_scalar_compare(coordinate,lo),h=htb_scalar_compare(coordinate,hi);if(l==HTB_CMP_LESS||h==HTB_CMP_GREATER)state=HTB_INTERSECTION_INVALID;else if(l==HTB_CMP_UNRESOLVED||h==HTB_CMP_UNRESOLVED||l==HTB_CMP_ERROR||h==HTB_CMP_ERROR)state=HTB_INTERSECTION_UNRESOLVED;}
    if(state==HTB_INTERSECTION_VALID){htb_vec2 normal;htb_vec2_init(t->arith,&normal);htb_scalar x,y,dot;htb_scalar_init(t->arith,&x);htb_scalar_init(t->arith,&y);htb_scalar_init(t->arith,&dot);if(!normal_at(t,&c->edge,&c->point,&normal,NULL,0)||!htb_scalar_mul(&x,&normal.x,&v->x)||!htb_scalar_mul(&y,&normal.y,&v->y)||!htb_scalar_add(&dot,&x,&y))state=HTB_INTERSECTION_INVALID;else{htb_cmp tangent=htb_scalar_compare_si(&dot,0);if(tangent==HTB_CMP_EQUAL)state=HTB_INTERSECTION_TANGENT;else if(tangent==HTB_CMP_UNRESOLVED||tangent==HTB_CMP_ERROR)state=HTB_INTERSECTION_UNRESOLVED;}htb_vec2_clear(&normal);htb_scalar_clear(&x);htb_scalar_clear(&y);htb_scalar_clear(&dot);}htb_vec2_clear(&ref);htb_vec2_clear(&a);htb_vec2_clear(&b);return state;
}
static int add_root(const htb_tiling*t,htb_intersection_list*list,const htb_scalar*root,const htb_edge_ref*edge,const htb_vec2*p,const htb_vec2*v,const htb_tile_id*tile){htb_intersection*c=htb_intersection_list_append(list);if(!c)return 0;c->edge=*edge;c->has_time=1;htb_scalar_set(&c->time,root);c->state=validate_candidate(t,c,p,v,tile);return 1;}
static int solve_edge(const htb_tiling*t,htb_intersection_list*list,const htb_vec2*p,const htb_vec2*v,const htb_tile_id*tile,const htb_edge_ref*edge,int known){
    htb_scalar ca,cb,cc,cd,A,B,C,disc,root,tmp,two,four;htb_scalar*all[]={&ca,&cb,&cc,&cd,&A,&B,&C,&disc,&root,&tmp,&two,&four};for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_init(t->arith,all[i]);htb_scalar_set_si(&two,2);htb_scalar_set_si(&four,4);int ok=boundary_coefficients(t,edge,&ca,&cb,&cc,&cd);
    if(ok)ok=htb_scalar_sqr(&A,&v->x)&&htb_scalar_sqr(&tmp,&v->y)&&htb_scalar_add(&A,&A,&tmp)&&htb_scalar_mul(&A,&A,&ca);
    if(ok)ok=htb_scalar_mul(&B,&p->x,&v->x)&&htb_scalar_mul(&tmp,&p->y,&v->y)&&htb_scalar_add(&B,&B,&tmp)&&htb_scalar_mul(&B,&B,&ca)&&htb_scalar_mul(&B,&B,&two)&&htb_scalar_mul(&tmp,&cb,&v->x)&&htb_scalar_add(&B,&B,&tmp)&&htb_scalar_mul(&tmp,&cc,&v->y)&&htb_scalar_add(&B,&B,&tmp);
    if(ok)ok=htb_scalar_sqr(&C,&p->x)&&htb_scalar_sqr(&tmp,&p->y)&&htb_scalar_add(&C,&C,&tmp)&&htb_scalar_mul(&C,&C,&ca)&&htb_scalar_mul(&tmp,&cb,&p->x)&&htb_scalar_add(&C,&C,&tmp)&&htb_scalar_mul(&tmp,&cc,&p->y)&&htb_scalar_add(&C,&C,&tmp)&&htb_scalar_add(&C,&C,&cd);
    htb_cmp az=ok?htb_scalar_compare_si(&A,0):HTB_CMP_ERROR;if(ok&&known){if(az==HTB_CMP_GREATER||az==HTB_CMP_LESS){htb_scalar_neg(&root,&B);ok=htb_scalar_div(&root,&root,&A)&&add_root(t,list,&root,edge,p,v,tile);}goto done;}if(ok&&az==HTB_CMP_EQUAL){htb_cmp bz=htb_scalar_compare_si(&B,0);if(bz==HTB_CMP_GREATER||bz==HTB_CMP_LESS){htb_scalar_neg(&root,&C);ok=htb_scalar_div(&root,&root,&B)&&add_root(t,list,&root,edge,p,v,tile);}goto done;}if(ok&&(az==HTB_CMP_UNRESOLVED||az==HTB_CMP_ERROR)){htb_intersection*c=htb_intersection_list_append(list);if(c){c->edge=*edge;c->state=HTB_INTERSECTION_UNRESOLVED;}else ok=0;goto done;}if(ok)ok=htb_scalar_sqr(&disc,&B)&&htb_scalar_mul(&tmp,&A,&C)&&htb_scalar_mul(&tmp,&tmp,&four)&&htb_scalar_sub(&disc,&disc,&tmp);if(ok){htb_cmp ds=htb_scalar_compare_si(&disc,0);if(ds==HTB_CMP_LESS)goto done;if(ds==HTB_CMP_UNRESOLVED||ds==HTB_CMP_ERROR){htb_intersection*c=htb_intersection_list_append(list);if(c){c->edge=*edge;c->state=HTB_INTERSECTION_UNRESOLVED;}else ok=0;goto done;}ok=htb_scalar_sqrt(&disc,&disc)&&htb_scalar_neg(&tmp,&B)&&htb_scalar_mul(&A,&A,&two)&&htb_scalar_sub(&root,&tmp,&disc)&&htb_scalar_div(&root,&root,&A)&&add_root(t,list,&root,edge,p,v,tile)&&htb_scalar_add(&root,&tmp,&disc)&&htb_scalar_div(&root,&root,&A)&&add_root(t,list,&root,edge,p,v,tile);}done:for(size_t i=0;i<sizeof(all)/sizeof(all[0]);i++)htb_scalar_clear(all[i]);return ok;
}
static int intersections(const htb_tiling*t,const htb_vec2*p,const htb_vec2*v,const htb_tile_id*tile,const char*entry,htb_intersection_list*list,char*error,size_t error_size){htb_edge_list edges;htb_edge_list_init(&edges);if(!enumerate_edges(t,tile,&edges,error,error_size))return 0;for(size_t i=0;i<edges.count;i++){int known=entry&&(strcmp(entry,edges.items[i].boundary_key)==0||same_supporting_curve(&edges.items[i],entry));if(!solve_edge(t,list,p,v,tile,&edges.items[i],known)){htb_edge_list_clear(&edges);snprintf(error,error_size,"failed to solve binary tile boundary");return 0;}}htb_edge_list_clear(&edges);return 1;}

static int edge_vertices(const htb_tiling*t,const htb_tile_id*tile,const htb_edge_ref*edge,htb_vec2*da,htb_vec2*db,htb_vec2*ra,htb_vec2*rb,char*error,size_t error_size){if(!edge_reference_vertices(t,tile,edge,ra,rb)){snprintf(error,error_size,"failed to construct binary edge endpoints");return 0;}return from_reference(t,ra,da,error,error_size)&&from_reference(t,rb,db,error,error_size);}
static int tile_measure(const htb_tiling*t,const htb_tile_id*tile,htb_measure_kind kind,htb_scalar*measure,char*error,size_t error_size){if(kind!=HTB_MEASURE_REFERENCE_EUCLIDEAN_AREA){snprintf(error,error_size,"requested exact measure is unavailable for binary@1");return 0;}htb_scalar h;htb_scalar_init(t->arith,&h);int ok=scalar_pow2(t->arith,&h,tile_level(tile))&&htb_scalar_sqr(measure,&h);htb_scalar_clear(&h);return ok;}
static int tile_center(const htb_tiling*t,const htb_tile_id*tile,htb_vec2*center,char*error,size_t error_size){htb_vec2 ref;htb_vec2_init(t->arith,&ref);htb_scalar h,half,three;htb_scalar_init(t->arith,&h);htb_scalar_init(t->arith,&half);htb_scalar_init(t->arith,&three);htb_scalar_parse_rational(&half,"1/2",error,error_size);htb_scalar_set_si(&three,3);int ok=scalar_pow2(t->arith,&h,tile_level(tile))&&scaled_integer(t->arith,&ref.x,tile_column(tile),&h)&&htb_scalar_mul(&half,&half,&h)&&htb_scalar_add(&ref.x,&ref.x,&half)&&htb_scalar_mul(&ref.y,&h,&three)&&htb_scalar_parse_rational(&half,"1/2",error,error_size)&&htb_scalar_mul(&ref.y,&ref.y,&half)&&from_reference(t,&ref,center,error,error_size);htb_scalar_clear(&h);htb_scalar_clear(&half);htb_scalar_clear(&three);htb_vec2_clear(&ref);return ok;}
static double area_gauss(int64_t n,int64_t k,int subdivisions){
    static const double nodes[]={-.8611363115940526,-.3399810435848563,.3399810435848563,.8611363115940526};static const double weights[]={.3478548451374539,.6521451548625461,.6521451548625461,.3478548451374539};double h=ldexp(1.0,(int)n);if(!isfinite(h)||h==0)return 0;double half=.5/subdivisions,total=0,inv=1/h;for(int sx=0;sx<subdivisions;sx++)for(int sy=0;sy<subdivisions;sy++){double sm=(sx+.5)/subdivisions,tm=1+(sy+.5)/subdivisions;for(int i=0;i<4;i++)for(int j=0;j<4;j++){double s=(double)k+sm+half*nodes[i],q=tm+half*nodes[j],value;if(h>=1){double d=s*s+(q+inv)*(q+inv);value=4*inv*inv/(d*d);}else{double x=h*s,y=h*q,d=x*x+(y+1)*(y+1);value=4*h*h/(d*d);}total+=weights[i]*weights[j]*value;}}return half*half*total;
}
static int disk_area_approx(const htb_tiling*t,const htb_tile_id*tile,double*area,double*estimated_error,char*error,size_t error_size){(void)t;double hi=area_gauss(tile_level(tile),tile_column(tile),4),lo=area_gauss(tile_level(tile),tile_column(tile),2);if(!isfinite(hi)||hi<=0){snprintf(error,error_size,"binary tile disk area is below the supported numerical range");return 0;}*area=hi;*estimated_error=fabs(hi-lo);return 1;}

